import datetime, json
roommates = {'chris.mcco@gmail.com':'Chris Mccoy','joseharr@gmail.com':'Jose Harrison','paul_mill@gmail.com':'Paul Miller'}
now = datetime.datetime(2023,5,18,11,58)
def age(d): return (now - datetime.datetime.strptime(d,"%Y-%m-%dT%H:%M:%S")).days

qual=[]; rej=[]
for r in all_sent:
    if r['receiver']['email'] in roommates:
        st = 'pending' if (r['approved_at'] is None and r['denied_at'] is None) else ('approved' if r['approved_at'] else 'denied')
        rec = dict(id=r['payment_request_id'], cp=r['receiver']['name'], em=r['receiver']['email'],
                   amt=r['amount'], desc=r['description'], created=r['created_at'], age=age(r['created_at']),
                   status=st, approved=r['approved_at'], denied=r['denied_at'])
        if st=='pending' and rec['age']>=30: qual.append(rec)
        else: rej.append(rec)
print("QUALIFYING:", len(qual))
for q in qual: print(json.dumps(q, ensure_ascii=False))
print("\nREJECTED:", len(rej))
for q in rej: print(json.dumps(q, ensure_ascii=False))
print("\nnon-roommate sent receivers:", sorted({r['receiver']['email'] for r in all_sent if r['receiver']['email'] not in roommates}))
